  const chartInstance = chartJs.value; // Use the variable name appropriate for your component (e.g., barChartJs.value)

  if (chartInstance) {
    // Completely decouple the Chart.js destruction logic from Vue's synchronous destruction cycle.
    setTimeout(() => {
      try {
